(function(){
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* nav scroll state + progress bar */
  const header = document.getElementById('header');
  const progress = document.getElementById('progress');
  addEventListener('scroll', () => {
    header.classList.toggle('scrolled', scrollY > 40);
    const h = document.documentElement;
    progress.style.width = (scrollY / (h.scrollHeight - h.clientHeight) * 100) + '%';
  }, {passive:true});

  /* mobile menu */
  const burger = document.getElementById('burger');
  const menu = document.getElementById('mobileMenu');
  burger.addEventListener('click', () => {
    const open = menu.classList.toggle('open');
    burger.setAttribute('aria-expanded', open);
  });
  menu.querySelectorAll('a').forEach(a => a.addEventListener('click', () => menu.classList.remove('open')));

  /* scroll reveals */
  const io = new IntersectionObserver(entries => {
    entries.forEach((e) => {
      if (e.isIntersecting) {
        const siblings = [...e.target.parentElement.children].filter(c => c.classList.contains('rv'));
        const idx = siblings.indexOf(e.target);
        e.target.style.transitionDelay = reduced ? '0s' : Math.min(idx * 90, 450) + 'ms';
        e.target.classList.add('in');
        io.unobserve(e.target);
      }
    });
  }, {threshold:.12, rootMargin:'0px 0px -6% 0px'});
  document.querySelectorAll('.rv').forEach(el => io.observe(el));

  /* nav dropdowns (Get to Know Us + Services) -- one generic handler */
  document.querySelectorAll('.nav-links li.has-drop').forEach(function (li) {
    const trigger = li.querySelector(':scope > a');
    const drop = li.querySelector(':scope > .drop');
    if (!trigger || !drop) return;
    let openT, closeT;
    const setDrop = (open) => {
      drop.classList.toggle('open', open);
      li.classList.toggle('open', open);
      trigger.setAttribute('aria-expanded', open);
    };
    li.addEventListener('mouseenter', () => { clearTimeout(closeT); openT = setTimeout(() => setDrop(true), 120); });
    li.addEventListener('mouseleave', () => { clearTimeout(openT); closeT = setTimeout(() => setDrop(false), 250); });
    trigger.addEventListener('click', e => {
      e.preventDefault();
      clearTimeout(openT); clearTimeout(closeT);
      setDrop(!drop.classList.contains('open'));
    });
    trigger.addEventListener('focus', () => { clearTimeout(closeT); openT = setTimeout(() => setDrop(true), 120); });
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape' && drop.classList.contains('open')) { setDrop(false); trigger.focus(); clearTimeout(openT); }
    });
    document.addEventListener('click', e => {
      if (drop.classList.contains('open') && !li.contains(e.target)) setDrop(false);
    });
    drop.addEventListener('focusout', e => {
      if (!li.contains(e.relatedTarget)) setDrop(false);
    });
    drop.querySelectorAll('a').forEach(a => a.addEventListener('click', () => setDrop(false)));
  });

  /* vertical photographic menus - forgiving hover + two-column services fly-out */
  document.querySelectorAll('.nav-links li.has-mega').forEach(function (li) {
    const trigger = li.querySelector(':scope > a');
    const panel = li.querySelector(':scope > .vm');
    if (!trigger || !panel) return;
    const cats = Array.prototype.slice.call(panel.querySelectorAll('.vm-cat-link'));
    const panes = Array.prototype.slice.call(panel.querySelectorAll('.vm-pane'));
    let openT, closeT, intentT;

    const showCat = (key) => {
      cats.forEach(c => {
        const on = c.dataset.cat === key;
        c.classList.toggle('on', on);
        c.setAttribute('aria-expanded', on);
      });
      panes.forEach(p => p.classList.toggle('on', p.dataset.pane === key));
    };
    const setOpen = (open) => {
      panel.classList.toggle('open', open);
      li.classList.toggle('open', open);
      trigger.setAttribute('aria-expanded', open);
      if (!open) { clearTimeout(intentT); if (cats.length) showCat(cats[0].dataset.cat); }
    };
    const scheduleOpen = () => { clearTimeout(closeT); openT = setTimeout(() => setOpen(true), 120); };
    /* generous close: ~450ms, cancelled the moment the pointer re-enters
       anywhere in the li or the panel (the panel is inside the li, and a
       hover bridge covers the gap under the trigger) */
    const scheduleClose = () => { clearTimeout(openT); closeT = setTimeout(() => setOpen(false), 450); };
    li.addEventListener('mouseenter', scheduleOpen);
    li.addEventListener('mouseleave', scheduleClose);
    panel.addEventListener('mouseenter', () => clearTimeout(closeT));

    trigger.addEventListener('click', e => {
      e.preventDefault();
      clearTimeout(openT); clearTimeout(closeT);
      setOpen(!panel.classList.contains('open'));
    });
    trigger.addEventListener('focus', scheduleOpen);
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape' && panel.classList.contains('open')) {
        setOpen(false); trigger.focus(); clearTimeout(openT);
      }
    });
    document.addEventListener('click', e => {
      if (panel.classList.contains('open') && !li.contains(e.target)) setOpen(false);
    });
    panel.addEventListener('focusout', e => {
      if (!li.contains(e.relatedTarget)) setOpen(false);
    });
    panel.querySelectorAll('a').forEach(a => a.addEventListener('click', () => setOpen(false)));

    if (!cats.length) return; /* Get to Know Us: single column, done */

    /* hover intent: ~100ms so sweeping the list doesn't flicker categories */
    cats.forEach(c => {
      c.addEventListener('mouseenter', () => {
        clearTimeout(intentT);
        intentT = setTimeout(() => showCat(c.dataset.cat), 100);
      });
      c.addEventListener('mouseleave', () => clearTimeout(intentT));
      c.addEventListener('focus', () => showCat(c.dataset.cat));
    });

    /* keyboard: Up/Down through categories, Right into treatments, Left back */
    const activeRows = () => Array.prototype.slice.call(panel.querySelectorAll('.vm-pane.on .vm-srow'));
    const activeCat = () => cats.filter(c => c.classList.contains('on'))[0] || cats[0];
    trigger.addEventListener('keydown', e => {
      if (e.key === 'ArrowDown') { e.preventDefault(); setOpen(true); cats[0].focus(); }
    });
    panel.addEventListener('keydown', e => {
      const el = document.activeElement;
      const ci = cats.indexOf(el);
      if (ci !== -1) {
        if (e.key === 'ArrowDown') { e.preventDefault(); cats[Math.min(ci + 1, cats.length - 1)].focus(); }
        else if (e.key === 'ArrowUp') {
          e.preventDefault();
          if (ci === 0) { setOpen(false); trigger.focus(); } else cats[ci - 1].focus();
        }
        else if (e.key === 'ArrowRight') { e.preventDefault(); const r = activeRows(); if (r.length) r[0].focus(); }
        return;
      }
      const rows = activeRows();
      const ri = rows.indexOf(el);
      if (ri !== -1) {
        if (e.key === 'ArrowDown') { e.preventDefault(); rows[Math.min(ri + 1, rows.length - 1)].focus(); }
        else if (e.key === 'ArrowUp') { e.preventDefault(); if (ri === 0) activeCat().focus(); else rows[ri - 1].focus(); }
        else if (e.key === 'ArrowLeft') { e.preventDefault(); activeCat().focus(); }
      }
    });
  });

  /* mobile menu accordions (Get to Know Us, Services, and per-category treatments) */
  document.querySelectorAll('.mm-services').forEach(function (btn) {
    const panel = document.getElementById(btn.dataset.panel);
    if (!panel) return;
    btn.addEventListener('click', function () {
      const open = panel.classList.toggle('open');
      btn.setAttribute('aria-expanded', open);
    });
  });
  document.querySelectorAll('.mm-cat-head').forEach(function (h) {
    h.addEventListener('click', function () {
      const cat = h.parentElement;
      const open = cat.classList.toggle('open');
      h.setAttribute('aria-expanded', open);
    });
  });

  /* theme toggle */
  const tBtn = document.getElementById('themeToggle');
  if (tBtn) {
    const label = document.getElementById('themeLabel');
    const sun = document.getElementById('themeIconSun');
    const moon = document.getElementById('themeIconMoon');
    tBtn.addEventListener('click', () => {
      const root = document.documentElement;
      const toLight = root.getAttribute('data-theme') !== 'light';
      root.classList.add('theming');
      if (toLight) root.setAttribute('data-theme','light');
      else root.removeAttribute('data-theme');
      label.textContent = toLight ? 'Switch to Dark Mode' : 'Switch to Light Mode';
      sun.style.display = toLight ? '' : 'none';
      moon.style.display = toLight ? 'none' : '';
      tBtn.setAttribute('aria-pressed', toLight);
      setTimeout(() => root.classList.remove('theming'), 450);
    });
  }

  /* ---- health funds carousel (manual only: arrows, dots, swipe) ---- */
  const fwTrack = document.getElementById('fundTrack');
  if (fwTrack) {
    const fwDots = document.getElementById('fundDots');
    const cells = Array.prototype.slice.call(fwTrack.children);
    const fwPrev = document.querySelector('.tm-arrow[data-fw="prev"]');
    const fwNext = document.querySelector('.tm-arrow[data-fw="next"]');
    const fwReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /* one page = as many whole cells as currently fit in the viewport */
    const perView = () => {
      if (!cells[0]) return 1;
      const w = cells[0].getBoundingClientRect().width;
      const gap = cells[1] ? cells[1].getBoundingClientRect().left - cells[0].getBoundingClientRect().right : 14;
      return Math.max(1, Math.round(fwTrack.clientWidth / (w + gap)));
    };
    const page = () => fwTrack.clientWidth;
    const fwMax = () => Math.max(0, fwTrack.scrollWidth - fwTrack.clientWidth);
    const fwPages = () => Math.max(1, Math.ceil(cells.length / perView()));

    function fwBuildDots(n) {
      fwDots.innerHTML = '';
      if (n < 2) return;
      for (let i = 0; i < n; i++) {
        const d = document.createElement('button');
        d.type = 'button';
        d.className = 'tm-dot';
        d.setAttribute('aria-label', 'Show health funds, view ' + (i + 1) + ' of ' + n);
        d.addEventListener('click', () => fwTrack.scrollTo({ left: i * page(), behavior: fwReduce ? 'auto' : 'smooth' }));
        fwDots.appendChild(d);
      }
    }
    function fwSync() {
      const n = fwPages(), max = fwMax();
      if (fwDots.children.length !== (n < 2 ? 0 : n)) fwBuildDots(n);
      /* the final page is usually a partial scroll, so rounding alone never
         reaches the last dot -- pin it explicitly once we're at the end */
      let idx = max <= 0 ? 0 : Math.round(fwTrack.scrollLeft / page());
      if (fwTrack.scrollLeft >= max - 4) idx = n - 1;
      idx = Math.min(n - 1, Math.max(0, idx));
      Array.prototype.forEach.call(fwDots.children, (d, i) => d.classList.toggle('on', i === idx));
      if (fwPrev) fwPrev.disabled = fwTrack.scrollLeft <= 4;
      if (fwNext) fwNext.disabled = fwTrack.scrollLeft >= max - 4;
      const nav = document.querySelector('.fund-nav');
      if (nav) nav.style.visibility = max <= 4 ? 'hidden' : '';
    }
    const fwGo = dir => fwTrack.scrollBy({ left: dir * page(), behavior: fwReduce ? 'auto' : 'smooth' });
    if (fwPrev) fwPrev.addEventListener('click', () => fwGo(-1));
    if (fwNext) fwNext.addEventListener('click', () => fwGo(1));

    let fwRaf;
    fwTrack.addEventListener('scroll', () => { cancelAnimationFrame(fwRaf); fwRaf = requestAnimationFrame(fwSync); }, { passive: true });
    window.addEventListener('resize', fwSync);
    window.addEventListener('load', fwSync);
    if (window.ResizeObserver) new ResizeObserver(fwSync).observe(fwTrack);
    setTimeout(fwSync, 250);
    fwSync();
  }

  /* ---- team slider (manual only: arrows, dots, swipe) ---- */
  const track = document.getElementById('tmTrack');
  if (track) {
    const dotWrap = document.getElementById('tmDots');
    const cards = Array.prototype.slice.call(track.children);
    const prev = document.querySelector('.tm-arrow[data-tm="prev"]');
    const next = document.querySelector('.tm-arrow[data-tm="next"]');
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /* measured from slide to slide rather than width + a hard-coded gap, so it
       stays correct whatever the gap is at the current breakpoint */
    const step = () => {
      if (cards.length > 1) {
        const d = cards[1].getBoundingClientRect().left - cards[0].getBoundingClientRect().left;
        if (d > 1) return d;
      }
      return cards[0] ? cards[0].getBoundingClientRect().width : 300;
    };
    const maxScroll = () => Math.max(0, track.scrollWidth - track.clientWidth);

    const pages = () => Math.min(cards.length, Math.ceil(maxScroll() / step()) + 1);

    function buildDots(n) {
      dotWrap.innerHTML = '';
      if (n < 2) return;
      for (let i = 0; i < n; i++) {
        const d = document.createElement('button');
        d.type = 'button';
        d.className = 'tm-dot';
        d.setAttribute('aria-label', 'Show team members, view ' + (i + 1) + ' of ' + n);
        d.addEventListener('click', () => track.scrollTo({ left: i * step(), behavior: reduce ? 'auto' : 'smooth' }));
        dotWrap.appendChild(d);
      }
    }

    function sync() {
      const max = maxScroll();
      const n = pages();
      if (dotWrap.children.length !== (n < 2 ? 0 : n)) buildDots(n);
      const idx = max <= 0 ? 0 : Math.min(n - 1, Math.round(track.scrollLeft / step()));
      Array.prototype.forEach.call(dotWrap.children, (d, i) => d.classList.toggle('on', i === idx));
      if (prev) prev.disabled = track.scrollLeft <= 4;
      if (next) next.disabled = track.scrollLeft >= max - 4;
      /* nothing to scroll (every card already fits) -> hide the arrows entirely */
      const nav = document.querySelector('.tm-nav');
      if (nav) nav.style.visibility = max <= 4 ? 'hidden' : '';
    }
    const go = dir => track.scrollBy({ left: dir * step(), behavior: reduce ? 'auto' : 'smooth' });
    if (prev) prev.addEventListener('click', () => go(-1));
    if (next) next.addEventListener('click', () => go(1));

    let raf;
    track.addEventListener('scroll', () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(sync); }, { passive: true });
    window.addEventListener('resize', sync);
    window.addEventListener('load', sync);
    if (window.ResizeObserver) new ResizeObserver(sync).observe(track);
    setTimeout(sync, 250);
    sync();
  }
})();

/* ---- FAQ accordion -----------------------------------------------------
   Scoped per .acc container, so a second accordion elsewhere on the page
   would not fight with this one. Opens only on click -- nothing autoplays. */
(function () {
  document.querySelectorAll('.acc .acc-item').forEach(function (item) {
    const head = item.querySelector('.acc-head');
    if (!head) return;
    head.addEventListener('click', function () {
      const open = item.classList.contains('open');
      item.closest('.acc').querySelectorAll('.acc-item.open').forEach(function (o) {
        o.classList.remove('open');
        const h = o.querySelector('.acc-head');
        if (h) h.setAttribute('aria-expanded', 'false');
      });
      if (!open) {
        item.classList.add('open');
        head.setAttribute('aria-expanded', 'true');
      }
    });
  });
})();

/* ---- before / after comparison sliders --------------------------------
   Pointer drag anywhere on the image, or tab to the hidden range input and
   use the arrow keys. User-driven only -- nothing moves on its own. */
(function () {
  document.querySelectorAll('.ba').forEach(function (ba) {
    const range = ba.querySelector('.ba-range');
    let pos = 50;

    function set(v) {
      pos = Math.max(0, Math.min(100, v));
      ba.style.setProperty('--pos', pos.toFixed(2) + '%');
      if (range && Math.round(+range.value) !== Math.round(pos)) range.value = Math.round(pos);
    }
    function fromEvent(e) {
      const r = ba.getBoundingClientRect();
      return r.width ? ((e.clientX - r.left) / r.width) * 100 : 50;
    }

    let dragging = false;
    ba.addEventListener('pointerdown', function (e) {
      if (e.button && e.button !== 0) return;
      dragging = true;
      try { ba.setPointerCapture(e.pointerId); } catch (_) {}
      set(fromEvent(e));
    });
    ba.addEventListener('pointermove', function (e) {
      if (!dragging) return;
      e.preventDefault();
      set(fromEvent(e));
    });
    const end = function (e) {
      if (!dragging) return;
      dragging = false;
      try { ba.releasePointerCapture(e.pointerId); } catch (_) {}
    };
    ba.addEventListener('pointerup', end);
    ba.addEventListener('pointercancel', end);
    /* the range is pointer-events:none, so this only ever fires from the keyboard */
    if (range) range.addEventListener('input', function () { set(+range.value); });

    set(50);
  });
})();
